parameters.pythonCode:
reference_cs = {
    1: 16.2, 2: 36.4, 3: 4.4, 4: 16.8, 5: 82.5,
    6: 91.4, 7: 82.8, 8: 60.3, 9: 96.6, 10: 31.9
}

groups = {}
unclassified = 0

for item in _items:
    r = item["json"]
    g = r.get("robson_group", 0)
    if g == 0:
        unclassified += 1
        continue
    if g not in groups:
        groups[g] = {'total': 0, 'cs': 0}
    groups[g]['total'] += 1
    if r.get("delivery_method", "") == "cs":
        groups[g]['cs'] += 1

total_births = len(_items)
results = []

for g in sorted(groups.keys()):
    info = groups[g]
    cs_rate = round((info['cs'] / info['total']) * 100, 1) if info['total'] > 0 else 0
    ref = reference_cs.get(g, 0)
    gap = round(cs_rate - ref, 1)

    flag = "OK"
    if gap > 10:
        flag = "HIGH"
    elif gap > 0:
        flag = "WATCH"

    results.append({
        "json": {
            "robson_group": g,
            "total_births": info['total'],
            "cs_count": info['cs'],
            "cs_rate_pct": cs_rate,
            "cdc_reference_pct": ref,
            "gap_pp": gap,
            "alert": flag
        }
    })

# Add summary row
overall_cs = sum(g['cs'] for g in groups.values())
results.append({
    "json": {
        "robson_group": "ALL",
        "total_births": total_births,
        "cs_count": overall_cs,
        "cs_rate_pct": round((overall_cs / total_births) * 100, 1) if total_births > 0 else 0,
        "cdc_reference_pct": "-",
        "gap_pp": "-",
        "alert": "SUMMARY",
        "unclassified_count": unclassified
    }
})

return results
